WITH cleaned AS (SELECT id, order_id, method, amount, paid_at, UPPER(method) AS method_upper FROM payments WHERE amount > 580), with_prev AS (SELECT *, LAG(paid_at) OVER (PARTITION BY method ORDER BY paid_at, id) AS prev_paid_at FROM cleaned), gaps AS (SELECT *, CASE WHEN prev_paid_at IS NULL OR paid_at > prev_paid_at + INTERVAL '14' DAY THEN 1 ELSE 0 END AS session_start_flag FROM with_prev), sessions_payments AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT method, DATE_TRUNC('WEEK', prev_paid_at) AS week_start, order_id, SIZE(COLLECT_SET(method)) AS num_methods, COUNT(DISTINCT method) AS distinct_methods, SUM(CASE WHEN method = 'paypal' THEN amount ELSE 0 END) AS paypal_amount FROM sessions_payments GROUP BY method, DATE_TRUNC('WEEK', prev_paid_at), order_id ORDER BY method NULLS LAST
